257	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
258	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
259	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
260	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
261	template <OptId Opt>
262	cudaError_t launch_fused_decoder_megakernel(
263	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
264	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
265	    int dev = 0;
266	    cudaError_t err = cudaGetDevice(&dev);
267	    if (err != cudaSuccess) return err;
268	    int n_sms = 0;
269	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
270	    if (err != cudaSuccess) return err;
271	
272	    int occ = 0;
273	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
274	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
275	        /*dynamicSMemBytes=*/0);
276	    if (err != cudaSuccess) return err;
277	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
278	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
279	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
280	    assert(occ >= 1 &&
281	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
282	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
283	           "reduce footprint or fall back to the L1 per-op path.");
284	    if (occ < 1) return cudaErrorLaunchOutOfResources;
285	
286	    const unsigned launch_ctas = (unsigned)n_sms;
287	    ctx.n_ctas = launch_ctas;
288	
289	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
290	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
291	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
292	
293	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
294	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
295	        ctx, params, tok, grad, lr, step, st);
296	    return cudaGetLastError();
297	}
